"""English editorial content. Internal links are localized by the build."""

def cta():
    return '''<div class="wrap band"><div><span class="eyebrow">A PLACE TO START</span><h2>Bring us a real task.</h2><p class="lead">First, agree on what a good result looks like. Then work out how to get there.</p></div><a class="btn" href="/contact/">Discuss your workflow <span>↗</span></a></div>'''

pages = {}
pages[''] = ('AI systems built around your work', '''<div class="wrap"><div class="hero"><div><span class="eyebrow">HARNESSLOOP / BUSINESS-SPECIFIC AI</span><h1>AI systems built around<br><em>your work.</em></h1><p class="lead">We design custom harnesses: the data, tools, workflows and checks that help AI do a particular job. Then we use feedback to test what should change.</p><div class="actions"><a class="btn" href="/contact/">Discuss your workflow <span>↗</span></a><a class="textlink" href="/how-it-works/">How it works ↗</a></div><p class="micro" style="margin-top:35px">SPECIFIC TASKS. CLEAR STANDARDS. CAREFUL IMPROVEMENT.</p></div><div class="visual document-study" aria-label="An illustrative extraction error: 15 business days in the source becomes 15 days in the extracted record"><div class="cap"><span class="micro">A SMALL DETAIL. A DIFFERENT RESULT.</span><span class="micro">Illustration</span></div><div class="study-sheet"><span class="micro">SOURCE / LINE 04</span><p>Delivery within<br><strong>15 business days.</strong></p><div class="study-divider"></div><span class="micro">EXTRACTED RECORD</span><p>Delivery within<br><s>15 days.</s></p><span class="review-mark">Review needed: preserve the time unit.</span></div><div class="visual-foot"><span>SYNTHETIC EXAMPLE</span><span>NOT A LIVE MODEL RUN</span></div></div></div><div class="strip"><div><b>Fit the task</b>Start with acceptance criteria</div><div><b>Test the change</b>Look for evidence, not impressions</div><div><b>Keep control</b>Make review and release explicit</div></div></div><section class="wrap"><div class="sectionhead"><div><span class="eyebrow">THE WORK AROUND THE MODEL</span><h2>A capable model is<br>only part of the job.</h2></div><p>Reliable work also depends on the right information, tools, rules and checks.</p></div><div class="cards"><div class="card"><span class="num">01 / CONTEXT</span><h3>A new batch of data changes the result.</h3><p>Make sources, task context and tool use part of the system, rather than stitching them together each time.</p></div><div class="card"><span class="num">02 / QUALITY</span><h3>The workflow runs. Is the output usable?</h3><p>Turn a good result into something you can check: business constraints, representative examples and review criteria.</p></div><div class="card"><span class="num">03 / FEEDBACK</span><h3>The same mistake needs fixing again.</h3><p>Use failures and human feedback to propose changes, then evaluate them independently before adoption.</p></div></div></section><section class="light"><div class="wrap split"><div><span class="eyebrow">TWO DISTINCT LOOPS</span><h2>One does the work.<br>One improves how it is done.</h2><p class="lead">A harness is the execution system around a model. It determines which information and tools are available, how the task proceeds and how the result is checked.</p><div class="flow"><span>Run</span><i>→</i><span>Task / execution / checks</span></div><div class="flow"><span>Improve</span><i>→</i><span>Feedback / evaluation / approval</span></div><div class="actions"><a class="textlink" href="/how-it-works/">Explore the approach ↗</a></div></div><div class="paperdemo"><div class="micro">DESIGN NOTE / 001</div><h3>A promising change<br>is not yet a release.</h3><div class="line"><span>Candidate</span><span>Try it in isolation</span></div><div class="line"><span>Evaluation</span><span>Check gains and regressions</span></div><div class="line"><span>Decision</span><span>Apply agreed approval rules</span></div><div class="line"><span>After release</span><span>Monitor and retain a rollback path</span></div></div></div></section><section class="wrap split"><div><span class="eyebrow">OUR FIRST FOCUS</span><h2>From source documents<br>to records you can check.</h2><p class="lead">Our initial focus is data and knowledge work: connecting extraction, source evidence, quality checks and human feedback in a traceable workflow.</p><div class="actions"><a class="btn secondary" href="/data-factory/">Explore the example ↗</a></div></div><div class="box"><div class="demohead"><span class="micro">DOCUMENT → STRUCTURED RECORD</span><span class="tag">Synthetic example</span></div><div class="result-row"><b>Input</b><span>A purchasing specification</span></div><div class="result-row"><b>Process</b><span>Extract fields → link sources → check rules</span></div><div class="result-row"><b>Output</b><span class="good">Traceable records and review questions</span></div><p>Missing information stays unknown. This example is not a customer result.</p></div></section>''')

pages['how-it-works'] = ('How it works', '''<div class="wrap subhero"><span class="eyebrow">HOW IT WORKS</span><h1>The model reasons.<br>The harness organizes the work.</h1><p class="lead">Context, tools, constraints and feedback need to work together. We design them around the standards your business uses to accept a result.</p></div><section class="wrap two"><div class="box"><span class="eyebrow">01 / RUN LOOP</span><h2>Complete the task within clear limits.</h2><p>Business input → context and tools → execution → quality checks → delivery or human review.</p><ul><li>Connect authorized data and tools, without assuming unrestricted access.</li><li>Keep sources, steps and exceptions visible. Allow the workflow to stop when uncertain.</li><li>Route results that cannot be assessed reliably to a person, rather than forcing a conclusion.</li></ul></div><div class="box"><span class="eyebrow">02 / IMPROVEMENT LOOP</span><h2>Use feedback to test the next version.</h2><p>Failures and feedback → candidate change → independent evaluation → release decision → monitoring.</p><ul><li>Adjust prompts, tool configuration or workflows within an agreed scope.</li><li>Check improvements and regressions on independent examples, not just the development set.</li><li>Require human approval or an agreed release gate before a candidate becomes the working version.</li></ul></div></section><section class="light"><div class="wrap"><span class="eyebrow">SYSTEM DESIGN</span><h2>Four parts to design together.</h2><div class="sysgrid"><div><h3>Model · reasoning</h3><p>The model and reasoning budget matched to the task.</p></div><div><h3>Information and tools · resources</h3><p>Authorized sources, evidence links and available tools.</p></div><div><h3>Workflow and permissions · boundaries</h3><p>Execution steps, permission scope and human checkpoints.</p></div><div><h3>Evaluation and feedback · evidence</h3><p>Acceptance criteria, failure categories and regression checks.</p></div></div><p class="lead">This is a system design approach. It does not mean every task can improve automatically, or that model weights are continuously retrained.</p></div></section><section class="wrap"><span class="eyebrow">WHAT WE DESIGN WITH YOU</span><h2>More than a one-off answer.</h2><div class="steps"><div class="step"><h3>A task-specific harness</h3><p>Task definitions, data and tool connections, permissions and human checkpoints.</p></div><div class="step"><h3>Practical quality criteria</h3><p>Representative examples, evaluation dimensions, failure categories and regression checks.</p></div><div class="step"><h3>A controlled improvement process</h3><p>Candidate-to-baseline comparisons, independent validation, release boundaries and rollback plans.</p></div><div class="step"><h3>Traceable execution</h3><p>Sources, versions, workflow steps and human decisions included in the pilot design.</p></div></div><p class="notice">These are service and pilot design directions. Specific capabilities, integrations and deliverables depend on the use case and the agreed scope.</p></section>''')

pages['data-factory'] = ('Data & knowledge', '''<div class="wrap subhero"><span class="eyebrow">DATA & KNOWLEDGE</span><h1>Extract the information.<br>Keep the evidence.</h1><p class="lead">Field counts tell only part of the story. We also ask where a value came from, whether it passes the checks and how to avoid the same error next time.</p></div><section class="wrap" style="padding-top:10px"><p class="notice">Interactive concept example. All documents, versions and check results below are synthetic. This is not customer data, a live model run or evidence of a measured quality improvement.</p><div class="tabs" role="tablist" aria-label="Example stages"><button role="tab" aria-selected="true" data-stage="0">01 Extract</button><button role="tab" aria-selected="false" data-stage="1">02 Check</button><button role="tab" aria-selected="false" data-stage="2">03 Propose a change</button></div><div class="two"><div class="box"><div class="demohead"><h3>Source document</h3><span class="tag">SYNTHETIC DOC-001</span></div><p class="source">[L1] Project: sample equipment purchase.<br>[L2] Quantity ordered: 20 units.<br>[L3] Unit price: CNY 1,200, including tax.<br>[L4] Delivery: 15 business days after order confirmation.<br>[L5] Shipping charges to be agreed by both parties.</p><p class="micro">SOURCE PRESERVED · EVIDENCE LINKED</p></div><div class="box" id="demo-output" aria-live="polite"></div></div><div class="box" style="margin-top:24px"><span class="eyebrow">BEFORE RELEASE</span><h3>A candidate is not an approved version.</h3><p>This example follows one known error into the improvement process. Adopting the candidate still requires independent examples, regression checks and the agreed release decision. Unverified results remain unknown.</p></div></section>''')

pages['research'] = ('Field notes', '''<div class="wrap subhero"><span class="eyebrow">FIELD NOTES</span><h1>The reasoning<br>behind the work.</h1><p class="lead">Notes on system design and demonstration methods. These are not customer case studies or completed performance evaluations.</p></div><section class="wrap" style="padding-top:10px"><article class="article"><small>NOTE 01</small><div><h3>Why separate execution from improvement?</h3><p>Doing a task and changing the system carry different risks. Keeping them separate makes it clearer who can change what, and when it takes effect.</p><details open><summary>Read the note</summary><p>The run loop uses a fixed version to carry out tasks. The improvement loop collects issues and proposes candidates. Each candidate needs independent evaluation and a release decision; one successful example is not permission to rewrite production workflows. Monitoring and a rollback version remain necessary after release.</p></details></div><span>↗</span></article><article class="article"><small>NOTE 02</small><div><h3>Classify failures before optimizing.</h3><p>Missing information, unsupported inference, unit conversion and lost sources call for different checks.</p><details><summary>Read the note</summary><p>Record the source location, extracted value and validation status for each field. Missing does not mean negative; uncertain does not mean wrong. Identify the failure type before deciding whether to change a rule, add context, adjust a tool or ask for human judgment.</p></details></div><span>↗</span></article><article class="article"><small>NOTE 03</small><div><h3>What would count as evidence of improvement?</h3><p>Better results on development examples may not carry over to the next batch. Independent tests and regression checks matter just as much.</p><details><summary>Read the note</summary><p>For a pilot, we recommend separating development examples from independent evaluation examples and considering quality, cost, latency and human review effort together. Without a baseline, an understood sample distribution and a defined evaluation scope, we do not report percentage gains.</p></details></div><span>↗</span></article><div class="notice">Research reference: <a class="textlink" href="https://github.com/rsi-gear/gear" target="_blank" rel="noopener noreferrer">GEAR open-source project ↗</a>. This reference indicates a research direction, not a partnership, endorsement or completed product integration.</div></section>''')

pages['contact'] = ('About & projects', '''<div class="wrap subhero"><span class="eyebrow">ABOUT & PROJECTS</span><h1>Start with the work.<br>Agree on what good looks like.</h1><p class="lead">HarnessLoop focuses on AI execution systems shaped around business needs. We work toward turning a specific data or knowledge task into a workflow that can be checked and improved.</p></div><section class="wrap two" style="padding-top:10px"><div><h2>Define a small, focused pilot.</h2><div class="steps"><div class="step"><h3>Understand the task</h3><p>Identify the work, the bottleneck and the risk boundaries.</p></div><div class="step"><h3>Establish a baseline</h3><p>Use authorized, de-identified examples to agree on acceptance criteria.</p></div><div class="step"><h3>Build the pilot</h3><p>Test a minimal workflow against quality and human review effort.</p></div><div class="step"><h3>Decide what comes next</h3><p>Use the evidence to set the integration scope, release plan and next iteration.</p></div></div></div><div class="box"><h3>Outline your project</h3><p>This tool creates a brief in your browser only. It does not send or save it. A contact channel will be added once confirmed.</p><form class="form" id="brief-form"><label>What task should AI help with?<input name="task" required maxlength="200" placeholder="For example: extract purchasing fields from supplier documents"></label><label>What is difficult today?<textarea name="pain" required maxlength="800" placeholder="For example: inconsistent formats and repeated manual checks"></textarea></label><label>What would make the result acceptable?<textarea name="criteria" required maxlength="800" placeholder="For example: every key field must link back to a source"></textarea></label><button class="btn" type="submit">Create local brief ↗</button></form><p class="micro">Do not enter patient details, personal customer data, passwords or confidential business information.</p><div id="brief-panel" class="hidden"><h3>Local brief created. Nothing has been sent.</h3><pre class="brief" id="brief"></pre><button class="btn secondary" id="copy-brief" type="button">Copy brief</button><p id="copy-status" role="status"></p></div></div></section>''')

pages['privacy'] = ('Privacy', '')  # Body is generated by release.privacy(); no duplicate copy here.
